const json = pm.response.json();
const now = new Date();
const runId = now.toISOString().replace(/\D/g, '').slice(0, 14);
pm.collectionVariables.set('runId', runId);
pm.environment.set('runId', runId);
pm.environment.set('runSuffix', runId.slice(-6));
pm.environment.set('adminToken', json.accessToken);
pm.environment.set('adminRefreshToken', json.refreshToken);
pm.environment.set('adminUserId', json.user.id);
if (json.user.organizationId) {
  pm.environment.set('organizationId', json.user.organizationId);
} else {
  pm.sendRequest({
    url: pm.variables.replaceIn('{{apiBase}}/organizations'),
    method: 'GET',
    header: { Authorization: 'Bearer ' + json.accessToken }
  }, function (error, response) {
    if (error) throw error;
    pm.test('Setup | organization resolved', function () { pm.expect(response.code).to.eql(200); });
    const payload = response.json();
    const organizations = Array.isArray(payload) ? payload : (Array.isArray(payload.data) ? payload.data : [payload]);
    pm.expect(organizations[0], 'At least one seeded organization is required').to.have.property('id');
    pm.environment.set('organizationId', organizations[0].id);
  });
}

